public void init()
{
    next init();
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance())
        && this.args().caller() && this.args().dataset()
        && this.args().dataset() == tablenum(RetailPeriodicDiscount))
    {
        RetailDiscountMultibuy periodicDiscountLocal = this.args().record();
        if (periodicDiscountLocal is RetailDiscountMultibuy)
        {
            RetailDiscountMultibuy multibuyDiscount = periodicDiscountLocal as RetailDiscountMultibuy;
            if (multibuyDiscount.MultibuyDiscountType == RetailDiscountTypeEnum::UnitPriceDiscAmt)
            {
                RBOMultibuyDiscountLine_priceDiscPct.label("@GlobalUnifiedPricing:GUPRetailDiscountTypeUnitPriceDiscAmt");
            }
        }
    }
}
